responseSchemaParserJs:
try {
    const parts = responseJson?.candidates?.[0]?.content?.parts;
    if (!parts || !Array.isArray(parts) || parts.length === 0) return { error: 'No response parts' };

    const source = parts[0];
    let rawText = typeof source === 'object' ? source.text : source;

    let jsonString = '';
    const start = rawText.indexOf('{');
    const end = rawText.lastIndexOf('}');
    if (start !== -1 && end > start) jsonString = rawText.substring(start, end + 1);
    else return { error: 'No JSON found' };

    let parsedData = JSON.parse(jsonString);
    const dataRoot = parsedData.data;
    const global = dataRoot.global;
    let rawCharList = dataRoot.characters || [];

    // --- Core Logic: Character Filtering ---
    const sourceName = (global.sourceCharacterName || '').trim();
    const hasContact = global.hasPhysicalContact === true;
    const involved = Array.isArray(global.involvedCharacters) ? global.involvedCharacters.map(n => typeof n === 'string' ? n.trim() : '') : [];

    const charList = rawCharList.filter(c => {
        const cName = (c.characterName || '').trim();
        if (!cName) return false;
        if (cName === sourceName) return true; // Always keep source character
        if (hasContact && involved.includes(cName)) return true; // Keep involved characters if contact exists
        return false; // Discard anyone else
    });

    // --- Helper: Format and Clean Tags ---
    const _f = (tag) => {
        if (!tag || typeof tag !== 'string' || tag.toLowerCase() === 'none') return '';
        let formatted = tag.trim().replace(/\s+/g, '_');
        return formatted.replace(/^_+|_+$/g, '');
    };

    // --- 1. Global / Base Part ---
    const baseTags = [];
    const addBaseArr = (arr) => { if (Array.isArray(arr)) arr.forEach(v => { const fv = _f(v); if(fv) baseTags.push(fv); }); };

    // Character Counts
    const counts = {};
    charList.forEach(c => {
        const t = (Array.isArray(c.subjectType) && c.subjectType.length > 0 ? c.subjectType[0] : '1girl').toLowerCase();
        counts[t] = (counts[t] || 0) + 1;
    });
    Object.entries(counts).forEach(([t, n]) => {
        if (n === 1) baseTags.push(t);
        else if (n > 1) baseTags.push(`${n}${t.replace(/^\d+/, '')}s`);
    });

    // Solo logic
    if (charList.length === 1 && !global.hasPhysicalContact) baseTags.push('solo');

    addBaseArr(global.time);
    addBaseArr(global.locationAndBackground);

    if (global.isNSFW) baseTags.push('nsfw');
    if (global.isBDSM) baseTags.push('bdsm');
    if (global.isUncensored) baseTags.push('uncensored');

    const baseString = baseTags.join(', ');

    // --- 2. Character Parts ---
    const sharedActionRaw = Array.isArray(global.interaction) && global.interaction.length > 0 ? global.interaction[0] : 'none';
    const sharedAction = _f(sharedActionRaw);

    const charStrings = charList.map(char => {
        const charTags = [];
        if (char.characterName) charTags.push(char.characterName.trim());

        const addArr = (arr) => { if (Array.isArray(arr)) arr.forEach(v => { const fv = _f(v); if(fv) charTags.push(fv); }); };

        if (Array.isArray(char.subjectType) && char.subjectType.length > 0) charTags.push(_f(char.subjectType[0]));

        addArr(char.hairstyle);
        addArr(char.expression);
        addArr(char.pose);

        // Logic: Interaction Overrides Standalone Action
        const role = char.interactionRole;
        if (role !== 'none' && sharedAction) {
            const prefix = { initiator: 'source#', receiver: 'target#', mutual: 'mutual#' }[role] || '';
            charTags.push(`${prefix}${sharedAction}`);
        } else {
            addArr(char.action);
        }

        addArr(char.clothing);
        addArr(char.props);
        addArr(char.specialStatus);

        return charTags.join(', ');
    });

    // --- 3. Final Pipe Merge ---
    const finalPrompt = [baseString, ...charStrings].filter(s => s).join(' | ');

    return { generalTagsString: finalPrompt, characterTags: [] };

} catch (e) {
    return { error: `Parser Error: ${e.message}` };
}

